import json, time

def save_checkpoint(task_id, state):
    checkpoint = {
        "task_id": task_id,
        "completed_steps": state["completed_steps"],
        "current_step": state["current_step"],
        "saved_at": time.time(),
    }
    with open(f"checkpoints/{task_id}.json", "w") as f:
        json.dump(checkpoint, f)

def run_long_task(task_id, steps):
    state = {"completed_steps": [], "current_step": 0}
    for i, step in enumerate(steps):
        result = execute(step)
        state["completed_steps"].append(result)
        state["current_step"] = i + 1
        if i % 5 == 0:
            save_checkpoint(task_id, state)
    save_checkpoint(task_id, state)

def resume_task(task_id, steps):
    checkpoint = load_checkpoint(task_id)
    if checkpoint is None:
        return run_long_task(task_id, steps)
    start = checkpoint["current_step"]
    state = {"completed_steps": checkpoint["completed_steps"], "current_step": start}
    for i in range(start, len(steps)):
        result = execute(steps[i])
        state["completed_steps"].append(result)
        state["current_step"] = i + 1
        if i % 5 == 0:
            save_checkpoint(task_id, state)
    save_checkpoint(task_id, state)
